import sys
import json
import os

def format_date(d):
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    reports_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    reports_data = []
    if os.path.exists(reports_path):
        with open(reports_path, 'r') as f:
            data = json.load(f)
            reports_data = data.get("results", [])

    records_by_entity = {}
    for record in reports_data:
        entity = record.get("recall_number")
        if entity:
            records_by_entity.setdefault(entity, []).append(record)

    FACT_MAPPING = {
        "fda.classified_30d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "classification date": ("fda_enforcement_reports", "center_classification_date")
        },
        "fda.terminated_180d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "termination date": ("fda_enforcement_reports", "termination_date")
        }
    }

    results = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            mapping = FACT_MAPPING.get(rule_id, {}).get(fact)
            if not mapping:
                pair_result[fact] = "ABSENT"
                continue

            doc, field = mapping

            if doc == "fda_enforcement_reports":
                records = records_by_entity.get(entity, [])
                values = set()
                for r in records:
                    val = r.get(field, "")
                    if val is not None:
                        val = str(val).strip()
                        if val:
                            values.add(val)

                if len(values) == 0:
                    pair_result[fact] = "ABSENT"
                elif len(values) > 1:
                    pair_result[fact] = "CONFLICT"
                else:
                    val = values.pop()
                    formatted_val = format_date(val)
                    pair_result[fact] = [formatted_val, doc]
            else:
                pair_result[fact] = "ABSENT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

