import sys
import json
import os

def format_date(date_str):
    if not date_str:
        return None
    date_str = str(date_str).strip()
    if len(date_str) == 8 and date_str.isdigit():
        return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:]}"
    return date_str

def main():
    if len(sys.argv) < 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, 'fda_enforcement_reports.json')

    fda_data = []
    if os.path.exists(fda_file):
        with open(fda_file, 'r') as f:
            data = json.load(f)
            if 'results' in data:
                fda_data = data['results']

    recalls = {}
    for item in fda_data:
        recall_number = item.get('recall_number')
        if not recall_number:
            continue
        if recall_number not in recalls:
            recalls[recall_number] = []
        recalls[recall_number].append(item)

    output = {}

    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_output = {}
        records = recalls.get(entity, [])

        for fact in facts:
            values = set()
            for record in records:
                val = None
                if fact == 'initiation date':
                    val = record.get('recall_initiation_date')
                elif fact == 'classification date':
                    val = record.get('center_classification_date')
                elif fact == 'termination date':
                    val = record.get('termination_date')

                if val:
                    formatted_val = format_date(val)
                    if formatted_val:
                        values.add(formatted_val)

            if len(values) == 0:
                pair_output[fact] = "ABSENT"
            elif len(values) == 1:
                pair_output[fact] = [list(values)[0], "fda_enforcement_reports"]
            else:
                pair_output[fact] = "CONFLICT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

