import sys
import json
import os

def format_date(d):
    if not d:
        return None
    d = d.strip()
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    fda_records = []
    if os.path.exists(fda_path):
        with open(fda_path, 'r') as f:
            data = json.load(f)
            fda_records = data.get('results', [])

    records_by_entity = {}
    for rec in fda_records:
        entity = rec.get('recall_number')
        if entity:
            records_by_entity.setdefault(entity, []).append(rec)

    field_map = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    output = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::', 1)
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        entity_records = records_by_entity.get(entity, [])

        for fact in facts:
            field = field_map.get(fact)
            if not field:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for rec in entity_records:
                val = rec.get(field)
                if val:
                    val = str(val).strip()
                if val:
                    formatted_val = format_date(val)
                    if formatted_val:
                        values.add(formatted_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact] = "CONFLICT"
            else:
                pair_result[fact] = [list(values)[0], "fda_enforcement_reports"]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

