import sys
import json
import os

def format_date(date_str):
    if not date_str:
        return "ABSENT"
    if len(date_str) == 8 and date_str.isdigit():
        return f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:]}"
    return date_str

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    reports_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    entities = {}

    if os.path.exists(reports_path):
        with open(reports_path, 'r') as f:
            reports_data = json.load(f)

        for report in reports_data.get('results', []):
            recall_number = report.get('recall_number')
            if not recall_number:
                continue
            if recall_number not in entities:
                entities[recall_number] = []
            entities[recall_number].append(report)

    output = {}

    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        records = entities.get(entity, [])

        for fact in facts:
            values = set()

            for record in records:
                val = ""
                if fact == "initiation date":
                    val = record.get("recall_initiation_date", "")
                elif fact == "classification date":
                    val = record.get("center_classification_date", "")
                elif fact == "termination date":
                    val = record.get("termination_date", "")

                values.add(format_date(val))

            if not values:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                val = values.pop()
                if val == "ABSENT":
                    pair_result[fact] = "ABSENT"
                else:
                    pair_result[fact] = [val, "fda_enforcement_reports"]
            else:
                pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

