import sys
import json
import os

def format_date(d):
    if not d:
        return None
    d = str(d).strip()
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d if d else None

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    fda_data = {}

    if os.path.exists(fda_path):
        with open(fda_path, 'r') as f:
            data = json.load(f)
            for result in data.get('results', []):
                recall_number = result.get('recall_number')
                if not recall_number:
                    continue

                if recall_number not in fda_data:
                    fda_data[recall_number] = {
                        'recall_initiation_date': set(),
                        'center_classification_date': set(),
                        'termination_date': set()
                    }

                init_date = format_date(result.get('recall_initiation_date'))
                if init_date:
                    fda_data[recall_number]['recall_initiation_date'].add(init_date)

                class_date = format_date(result.get('center_classification_date'))
                if class_date:
                    fda_data[recall_number]['center_classification_date'].add(class_date)

                term_date = format_date(result.get('termination_date'))
                if term_date:
                    fda_data[recall_number]['termination_date'].add(term_date)

    output = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::', 1)
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_output = {}
        for fact in facts:
            if fact == 'initiation date':
                field = 'recall_initiation_date'
            elif fact == 'classification date':
                field = 'center_classification_date'
            elif fact == 'termination date':
                field = 'termination_date'
            else:
                continue

            if entity not in fda_data:
                pair_output[fact] = "ABSENT"
            else:
                values = fda_data[entity][field]
                if len(values) == 0:
                    pair_output[fact] = "ABSENT"
                elif len(values) == 1:
                    pair_output[fact] = [list(values)[0], "fda_enforcement_reports"]
                else:
                    pair_output[fact] = "CONFLICT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

